package dev.s7a.strata.runtime

import dev.s7a.strata.element.Element
import dev.s7a.strata.geometry.Constraints
import dev.s7a.strata.geometry.IntSize
import dev.s7a.strata.input.InputResult
import dev.s7a.strata.input.KeyboardEvent
import dev.s7a.strata.input.PointerEvent
import dev.s7a.strata.input.TextInputEvent
import dev.s7a.strata.node.DeclarationProjectionNode
import dev.s7a.strata.node.StateObserverNode
import dev.s7a.strata.runtime.diagnostics.UiRenderMetric
import dev.s7a.strata.runtime.diagnostics.UiRenderMonitor
import dev.s7a.strata.runtime.diagnostics.UiRenderOperation
import dev.s7a.strata.runtime.render.DrawCommand
import dev.s7a.strata.runtime.semantics.SemanticsEntry
import dev.s7a.strata.runtime.spi.RuntimeDeclaration
import dev.s7a.strata.runtime.spi.RuntimeTextInputFocus
import dev.s7a.strata.runtime.spi.RuntimeUiDiagnosticsOwner
import dev.s7a.strata.spi.InternalStrataRuntimeApi
import dev.s7a.strata.state.StateObservation
import dev.s7a.strata.ui.UiCloseReason
import kotlin.jvm.JvmSynthetic
import dev.s7a.strata.ui.UiSession as EventUiSession

// Why: this public owner intentionally exposes each retained lifecycle, frame, input, and inspection operation through one guarded boundary.

/**
 * A retained, platform-neutral UI tree.
 *
 * Every operation is confined to the execution owner that creates this tree.
 * Operational methods and [close] are not reentrant.
 * The [state] property may be read under the execution owner during an active callback.
 * An empty tree measures to [IntSize.Zero].
 * An empty tree performs no layout work and returns empty paint, input, and semantics results.
 * A complete description is validated before mutation.
 * Structural validation and local validation-hook failures leave an active tree unchanged and available for retry.
 * Any failure after validation begins reconciliation, lifecycle work, or a pipeline operation poisons the tree.
 * The tree clears retained ownership and attempts cleanup.
 * Cleanup preserves the primary [Throwable] instance and suppresses later distinct failures on it.
 */
@OptIn(InternalStrataRuntimeApi::class)
@Suppress("TooManyFunctions")
public class UiTree(
    eventSession: EventUiSession? = null,
) : AutoCloseable,
    RuntimeUiDiagnosticsOwner {
    private val ownerGuard: OwnerGuard = OwnerGuard()
    private var closeRequested = false
    private val fallbackSession = if (eventSession == null) UnpresentedUiSession(::requestClose) else null
    private val callbackSession = eventSession ?: checkNotNull(fallbackSession)

    /**
     * Shared nullable diagnostics gate used by the owning session.
     */
    internal val monitoring = RenderMonitoring()

    /**
     * Optional session owner used to track independently evaluated deferred regions.
     */
    internal var stateObservation: StateObservation? = null
    private val dirtyTracker = DirtyTracker(monitoring)
    private val registry = NodeOwnershipRegistry()
    private val pipeline = Pipeline(ownerGuard, monitoring, dirtyTracker)
    private val observedSources = ObservedSourceRegistry(monitoring)
    private val lifecycle =
        LifecycleManager(registry, ownerGuard, dirtyTracker, monitoring, callbackSession) { entry ->
            val failures = FailureAccumulator()
            if (entry is RetainedNode) {
                failures.capture { entry.contentObservation?.close() }
                entry.contentObservation = null
            }
            (entry.node as? StateObserverNode)?.let { node -> failures.capture { observedSources.remove(node) } }
            failures.capture { pipeline.entryWillCleanup(entry) }
            failures.throwIfPresent()
        }
    private val reconciler = Reconciler(lifecycle, dirtyTracker, observedSources, monitoring) { stateObservation }
    private val validator = DescriptionValidator()
    private var currentState: TreeState = TreeState.Active
    private var root: RetainedNode? = null
    private var operationActive: Boolean = false
    private var nextDeclarationId: Long = 1L

    /**
     * Projects reconciled declarations without executing measurement, layout, paint, or semantics.
     */
    internal fun <T> projectDeclarations(project: (RuntimeDeclaration) -> T): T =
        pipelineOperation {
            val retained = checkNotNull(root) { "Declaration projection requires an attached root." }
            reconciler.refreshProjectedChildren(retained, validator)
            lifecycle.attachPending(retained)
            project(declaration(retained))
        }

    private fun declaration(entry: RetainedNode): RuntimeDeclaration =
        RuntimeDeclaration(
            declarationId(entry),
            entry.element,
            (entry.node as? DeclarationProjectionNode)?.declarationProjection ?: entry.element.projection,
            entry.modifiers.snapshotMap { modifier -> RuntimeDeclaration.Modifier(declarationId(modifier), modifier.element, (modifier.node as? DeclarationProjectionNode)?.declarationProjection ?: modifier.element.projection) },
            entry.children.snapshotMap(::declaration),
        )

    /**
     * Creates an owned snapshot list without temporary empty or singleton map buffers.
     */
    private inline fun <T, R> List<T>.snapshotMap(transform: (T) -> R): List<R> =
        when (size) {
            0 -> emptyList()
            1 -> listOf(transform(this[0]))
            else -> map(transform)
        }

    private fun declarationId(entry: RetainedEntry): Long {
        if (entry.declarationId == 0L) {
            check(nextDeclarationId < Long.MAX_VALUE) { "Declaration identity space is exhausted." }
            entry.declarationId = nextDeclarationId++
        }
        return entry.declarationId
    }

    @InternalStrataRuntimeApi
    override fun startRenderMonitoring(): UiRenderMonitor = startMonitoring { }

    @InternalStrataRuntimeApi
    override fun startRenderMonitoring(maxNodeRecords: Int): UiRenderMonitor = startMonitoring(maxNodeRecords) { }

    /**
     * Adds the owning session's boundary check without exposing its implementation to callers.
     */
    internal fun startMonitoring(
        maxNodeRecords: Int = 4096,
        ownerBoundary: () -> Unit,
    ): UiRenderMonitor {
        ownerGuard.check()
        check(operationActive.not() && currentState === TreeState.Active) { "Monitoring requires an idle active tree." }
        ownerBoundary()
        require(maxNodeRecords in 1..65_536) { "Invalid render monitoring node-record capacity." }
        check(monitoring.collector == null) { "Render monitoring is already active." }
        val collector =
            RenderMonitorImpl(
                boundary = {
                    check(operationActive.not() && currentState === TreeState.Active) { "Monitoring requires an idle active tree." }
                    ownerBoundary()
                },
                onClose = { monitoring.collector = null },
                activeSubscriptions = observedSources.activeSubscriptions,
                monitoring = monitoring,
                maxNodeRecords = maxNodeRecords,
            )
        root?.let { collector.baseline(it.effectiveRoot) }
        monitoring.collector = collector
        return collector
    }

    /**
     * The current lifecycle state, read under the tree's execution owner.
     *
     * Reading this property from another execution owner fails without changing the tree.
     */
    public val state: TreeState
        get() {
            ownerGuard.check()
            return currentState
        }

    /**
     * Returns the detached identity of the current editable focus interval to its owning session.
     *
     * @return the committed editable interval, or null without an accepting editable focus target.
     * @throws IllegalStateException when read from another execution owner, during a tree operation, or after terminal cleanup.
     */
    @JvmSynthetic
    internal fun currentTextInputFocus(): RuntimeTextInputFocus? {
        ownerGuard.check()
        check(operationActive.not()) { "A tree operation is already active." }
        check(currentState === TreeState.Active) { "The retained tree is not active." }
        return pipeline.textInputFocus
    }

    /**
     * Returns the whole-tree change token used by an owning session's frame cache.
     *
     * The token changes when retained phase or structural work is recorded and is read only under the tree's execution owner.
     *
     * @return the current whole-tree change token.
     * @throws IllegalStateException when read from another execution owner.
     */
    @JvmSynthetic
    internal fun currentRevision(): Long {
        ownerGuard.check()
        return dirtyTracker.revision
    }

    /**
     * Delivers one explicit host timestamp to retained time-aware nodes.
     *
     * @param time timestamp from the owning host clock.
     */
    internal fun advanceFrame(time: FrameTime) {
        pipelineOperation {
            root?.let { retainedRoot -> pipeline.advanceFrame(retainedRoot, time) }
        }
    }

    /**
     * Synchronizes only pending retained geometry for an owning session with an already successful frame.
     *
     * Dirty measurement refreshes retained dynamic children as ordinary measurement does.
     * Session content, source cutoffs, time, painting, semantics, and frame snapshots remain frame work.
     * The ordinary public input methods retain their strict laid-out-tree precondition.
     *
     * @param constraints last successfully committed root constraints supplied by the owning session.
     * @throws Throwable when geometry fails; the tree is poisoned and cleaned before the event can be dispatched.
     * @throws IllegalStateException for an inactive or reentrant operation, or one from another execution owner.
     */
    @JvmSynthetic
    internal fun synchronizeInputGeometry(constraints: Constraints) {
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation
            if (pipeline.hasPendingMeasure(retainedRoot)) {
                reconciler.refreshDynamicChildren(retainedRoot, validator)
                lifecycle.attachPending(retainedRoot)
            }
            pipeline.synchronizeInputGeometry(retainedRoot, constraints)
        }
    }

    /**
     * Captures every retained external observation under the execution owner before any source value is committed.
     * A callback failure poisons this tree and releases captured state through ordinary node cleanup.
     */
    internal fun captureFrameState() {
        pipelineOperation {
            observedSources.capture()
            root?.let(pipeline::captureFrameState)
        }
    }

    /**
     * Commits the previously captured observations under the execution owner before declarative frame work.
     * A callback failure poisons this tree and preserves that failure through cleanup.
     */
    internal fun commitFrameState() {
        pipelineOperation {
            observedSources.commit()
            root?.let(pipeline::commitFrameState)
        }
    }

    /**
     * Releases sources left unreferenced by the completed owner-confined session frame or attachment.
     * Replacements keep their existing committed and pending snapshots; cleanup failures poison this tree.
     */
    internal fun finishFrameState() {
        pipelineOperation(observedSources::finishFrame)
    }

    /**
     * Applies pending source-backed declarations before a session checks retained frame identity.
     */
    internal fun refreshObservedContent() {
        pipelineOperation {
            root?.let { retainedRoot ->
                if (reconciler.refreshObservedContent(retainedRoot, validator)) lifecycle.attachPending(retainedRoot)
            }
        }
    }

    /**
     * Resumes session-scoped resources of the retained tree without changing ordinary lifecycle ownership.
     * Calls run parent-first under the execution owner and a failure poisons this tree after best-effort cleanup.
     */
    internal fun sessionAttached() {
        pipelineOperation {
            root?.let(pipeline::sessionAttached)
        }
    }

    /**
     * Suspends session-scoped resources while retaining node identity and layout under the execution owner.
     * Every callback is attempted; a failure poisons this tree and preserves the primary exception through cleanup.
     */
    internal fun sessionDetached() {
        pipelineOperation {
            root?.let(pipeline::sessionDetached)
        }
    }

    /**
     * Reconciles a complete immutable element description.
     *
     * Validation visits the complete description and runs each element's local validation hook.
     * It rejects duplicate keyed direct siblings before retained state changes.
     * A validation failure leaves the active tree unchanged.
     * Reconciliation reuses compatible nodes, creates detached nodes for additions, and attaches newly installed nodes parent-first.
     * A failure from reconciliation, node creation or update, lifecycle work, or cleanup poisons the tree.
     * The operation rethrows the primary failure after cleanup attempts.
     *
     * @param description the proposed root description.
     * @throws Throwable when a validation hook fails before mutation, or when reconciliation, lifecycle, or cleanup fails after validation.
     * The original throwable is propagated unchanged.
     * @throws IllegalStateException when the operation is called from another execution owner.
     * It is also thrown when the operation re-enters an active operation or the tree is not active.
     */
    public fun update(description: Element) {
        beginOperation()
        try {
            validator.validate(description)
            runCatching {
                observedSources.beginOperation()
                val nextRoot = reconciler.reconcileRoot(root, description)
                root = nextRoot
                reconciler.markInstalled(nextRoot)
                lifecycle.attachPending(nextRoot)
                observedSources.endOperation()
            }.getOrElse { failure -> poison(failure) }
        } finally {
            endOperation()
        }
    }

    /**
     * Measures the retained tree under [constraints].
     *
     * An empty tree returns [IntSize.Zero].
     * A clean node with equal constraints may reuse its retained size and skip its measure callback.
     * Measurement invalidation reruns local measurement and marks local layout, paint, and semantics work dirty.
     * It propagates measurement work to ancestors without dirtying descendants directly.
     * A callback or scope exception poisons the tree after pipeline work begins only when it escapes the owning callback.
     *
     * @param constraints the root constraints.
     * @return the measured root size, or [IntSize.Zero] when no root is installed.
     * @throws Throwable when a measure callback or scope operation fails after pipeline work begins.
     * The original throwable is propagated unchanged after cleanup attempts.
     * @throws IllegalStateException when the operation is called from another execution owner.
     * It is also thrown when the operation re-enters an active operation or the tree is not active.
     */
    public fun measure(constraints: Constraints): IntSize =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation IntSize.Zero
            reconciler.refreshDynamicChildren(retainedRoot, validator)
            lifecycle.attachPending(retainedRoot)
            pipeline.measure(retainedRoot, constraints)
        }

    /**
     * Places every measured node that participates in the current pass.
     *
     * An empty tree performs no work.
     * A non-empty tree must have a completed measure pass with no pending measure work.
     * If that precondition fails, the tree is poisoned.
     * A clean node may skip its layout callback while retained placements are reused.
     * Layout invalidation reruns local placement and marks local paint and semantics work dirty.
     * Ancestor traversal reaches an invalidated node only while that node is currently placed.
     * Descendants are not dirtied by layout invalidation.
     * Unmeasured or unplaced children are excluded from subsequent layout, paint, input, and semantics work.
     *
     * @throws IllegalStateException when the root has not been measured or measurement remains pending.
     * It is also thrown when the operation is called from another execution owner, re-enters an active operation, or the tree is not active.
     * @throws Throwable when a layout callback or scope operation throws after pipeline work begins and the exception escapes the callback.
     * The original throwable is propagated unchanged after cleanup attempts.
     */
    public fun layout() {
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation
            pipeline.requireMeasuredRoot(retainedRoot)
            pipeline.layout(retainedRoot)
        }
    }

    /**
     * Paints the laid-out tree in parent-before-child order.
     *
     * An empty tree returns an empty read-only list.
     * A non-empty tree must be laid out with no pending measurement or layout work.
     * If that precondition fails, the tree is poisoned.
     * A clean node reuses its complete local display list and combines it with current accumulated coordinates.
     * Commands preserve local emission order.
     * The core applies no implicit node or parent clipping.
     * Valid local overflow outside those bounds is retained.
     *
     * @return an read-only list of retained commands with bounds in accumulated tree coordinates.
     * @throws IllegalStateException when layout is incomplete or geometry remains pending.
     * It is also thrown when the operation is called from another execution owner, re-enters an active operation, or the tree is not active.
     * @throws Throwable when a paint callback or scope operation throws after pipeline work begins and the exception escapes the callback.
     * The original throwable is propagated unchanged after cleanup attempts.
     */
    public fun paint(): List<DrawCommand> =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation emptyList()
            pipeline.requirePlacedRoot(retainedRoot)
            pipeline.paint(retainedRoot)
        }

    /**
     * Dispatches [event] to the reverse paint-order hit path.
     *
     * An empty tree returns [InputResult.Ignored].
     * A non-empty tree must be laid out with no pending measurement or layout work.
     * If that precondition fails, the tree is poisoned.
     * Hit testing uses half-open accumulated bounds without implicit parent clipping.
     * The deepest and latest-painted hit node runs first.
     * [InputResult.Ignored] bubbles to earlier candidates.
     * [InputResult.Consumed] stops dispatch.
     * A captured move or matching-button drag or release bypasses bounds and ancestor clips and stops propagation even when the owner returns ignored.
     * Capture is acquired only by a capable node's consumed press and is cleared before the matching release callback.
     * A callback failure poisons the tree only when it escapes the callback.
     *
     * @param event the event in tree coordinates.
     * @return consumed when a node handled the event, otherwise ignored.
     * @throws IllegalStateException when layout is incomplete or geometry remains pending.
     * It is also thrown when the operation is called from another execution owner, re-enters an active operation, or the tree is not active.
     * @throws Throwable when a pointer callback fails after pipeline work begins.
     * The original throwable is propagated unchanged after cleanup attempts.
     */
    public fun dispatchPointer(event: PointerEvent): InputResult =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation InputResult.Ignored
            pipeline.requirePlacedRoot(retainedRoot)
            pipeline.dispatch(retainedRoot, event)
        }

    /**
     * Dispatches [event] to the currently focused logical component.
     *
     * An empty tree returns [InputResult.Ignored].
     * A non-empty tree must have completed layout with no pending geometry work.
     * Focused modifier nodes run from innermost to outermost and then the component node until one consumes the event.
     * If they all ignore a Tab press, focus moves cyclically through visible accepting logical owners in parent-before-child and declared sibling paint order.
     * Shift reverses traversal; other modifier bits do not change its direction.
     *
     * @param event immutable keyboard event.
     * @return consumed when focused behavior handles the event or Tab selects an eligible owner, otherwise ignored.
     * @throws IllegalStateException when layout is incomplete, the call is from another execution owner, another operation is active, or the tree is not active.
     * @throws Throwable when focused behavior fails; the original throwable escapes unchanged after cleanup attempts.
     */
    public fun dispatchKeyboard(event: KeyboardEvent): InputResult =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation InputResult.Ignored
            pipeline.requirePlacedRoot(retainedRoot)
            pipeline.dispatchKeyboard(retainedRoot, event)
        }

    /**
     * Dispatches [event] to the currently focused logical component.
     *
     * An empty tree or a tree without focus returns [InputResult.Ignored].
     * A non-empty tree must have completed layout with no pending geometry work.
     * Focused component and modifier nodes run from the component node toward outer modifiers until one consumes the event.
     *
     * @param event immutable committed-character or preedit event.
     * @return consumed when focused behavior handles the event, otherwise ignored.
     * @throws IllegalStateException when layout is incomplete, the call is from another execution owner, another operation is active, or the tree is not active.
     * @throws Throwable when focused behavior fails; the original throwable escapes unchanged after cleanup attempts.
     */
    public fun dispatchTextInput(event: TextInputEvent): InputResult =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation InputResult.Ignored
            pipeline.requirePlacedRoot(retainedRoot)
            pipeline.dispatchTextInput(event)
        }

    /**
     * Cancels capture and clears hover and focus when a retained session detaches or resets input without disposing this tree.
     *
     * The operation is confined to the execution owner and uses the most recently committed placement bounds even when later geometry became dirty.
     * It clears capture before cancellation, then invokes retained hover nodes, including unplaced entries, in deepest/latest-painted-first order and clears focus.
     * Every independent cleanup is attempted even when cancellation fails; the tree is otherwise retained for continued input or reattachment.
     *
     * @throws IllegalStateException when the call is from another execution owner, another operation is active, or this tree is not active.
     * @throws Throwable when a cancellation, hover, or focus callback fails; the exact failure remains primary while the tree is poisoned and cleaned.
     */
    @JvmSynthetic
    internal fun clearInputState() {
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation
            pipeline.clearInputState(retainedRoot)
        }
    }

    /**
     * Collects unresolved semantics in parent-before-child order.
     *
     * An empty tree returns an empty read-only list.
     * A non-empty tree must be laid out with no pending measurement or layout work.
     * If that precondition fails, the tree is poisoned.
     * A clean node reuses its complete local semantics payload and combines it with current accumulated bounds.
     * Semantics invalidation affects only that node's local payload.
     * Text remains unresolved for the platform adapter.
     * Callback failures poison the tree.
     *
     * @return an read-only list of entries with accumulated tree-coordinate bounds.
     * @throws IllegalStateException when layout is incomplete or geometry remains pending.
     * It is also thrown when the operation is called from another execution owner, re-enters an active operation, or the tree is not active.
     * @throws Throwable when a semantics callback or scope operation throws after pipeline work begins.
     * The exception must escape the callback.
     * The original throwable is propagated unchanged after cleanup attempts.
     */
    public fun semantics(): List<SemanticsEntry> =
        pipelineOperation {
            val retainedRoot = root ?: return@pipelineOperation emptyList()
            pipeline.requirePlacedRoot(retainedRoot)
            pipeline.semantics(retainedRoot)
        }

    /**
     * Cleans all retained ownership in descendant-first order.
     *
     * Close is confined to the execution owner and non-reentrant.
     * It records [TreeState.Closed] before any cleanup callback.
     * It clears retained ownership and pipeline-held references before cleanup and remains closed even when cleanup fails.
     * Cleanup visits descendants before parents and later siblings before earlier siblings.
     * Cleanup attempts detach only after an attach attempt.
     * Cleanup disposes every claimed node.
     * Cleanup continues after failures and rethrows the first [Throwable] instance with later distinct failures suppressed.
     * A repeated close after the operation has returned is a no-op.
     *
     * @throws IllegalStateException when the operation is called from another execution owner or re-enters an active operation.
     * @throws Throwable when a cleanup callback fails.
     * The first cleanup throwable is propagated unchanged after all cleanup attempts.
     */
    override fun close() {
        ownerGuard.check()
        check(operationActive.not()) { "A tree operation is already active." }
        if (currentState === TreeState.Closed) {
            return
        }
        operationActive = true
        try {
            currentState = TreeState.Closed
            fallbackSession?.finish(UiCloseReason.Closed)
            val capturedRoot = root
            root = null
            registry.clear()
            val failures = FailureAccumulator()
            capturedRoot?.let(lifecycle::prepareCleanup)
            failures.capture { pipeline.releaseRetainedReferences() }
            if (capturedRoot != null) {
                failures.addOptional(lifecycle.cleanup(capturedRoot))
            }
            failures.addOptional(reconciler.cleanupProvisionals())
            failures.capture(observedSources::close)
            monitoring.release()
            failures.throwIfPresent()
        } finally {
            endOperation()
        }
    }

    private fun beginOperation() {
        ownerGuard.check()
        check(operationActive.not()) { "A tree operation is already active." }
        check(currentState === TreeState.Active) { "The retained tree is not active." }
        operationActive = true
    }

    private inline fun <T> pipelineOperation(block: () -> T): T {
        beginOperation()
        try {
            return runCatching {
                observedSources.beginOperation()
                val result = block()
                observedSources.endOperation()
                result
            }.getOrElse { failure -> poison(failure) }
        } finally {
            endOperation()
        }
    }

    private fun endOperation() {
        operationActive = false
        if (closeRequested) {
            closeRequested = false
            if (currentState == TreeState.Active) close()
        }
    }

    private fun requestClose() {
        ownerGuard.check()
        if (currentState !== TreeState.Active) return
        if (operationActive) closeRequested = true else close()
    }

    private fun poison(failure: Throwable): Nothing {
        if (monitoring.operation == UiRenderOperation.Frame) monitoring.record(UiRenderMetric.FrameFailure)
        monitoring.failed()
        currentState = TreeState.Poisoned
        fallbackSession?.finish(UiCloseReason.Failed)
        val capturedRoot = root
        root = null
        registry.clear()
        val failures = FailureAccumulator(failure)
        capturedRoot?.let(lifecycle::prepareCleanup)
        failures.capture { pipeline.releaseRetainedReferences() }
        if (capturedRoot != null) {
            failures.addOptional(lifecycle.cleanup(capturedRoot))
        }
        failures.addOptional(reconciler.cleanupProvisionals())
        failures.capture(observedSources::close)
        monitoring.release()
        failures.throwFirst()
    }
}
